remaining_probes.source:
using symbol "std:io" @print;
symbol @number:u64;
proc run()->void {
 effect @number <-1u64;
 defer {behave @print(@number);};
}
run();

using symbol "std:io" @print;
data Item {value:u64;}
proc run()->void {
 owned region r:Item <-make Item(capacity=256u64){value<-1u64};
 proc action=proc()->Item {behave @print(root(r).value); return root(r);};
 defer {action();};
}
run();

using symbol "std:io" @print;
data Item {value:u64;}
region symbol @arena:Item;
symbol @reader:proc()->const u64;
proc run()->void {
  effect @arena <-make Item(capacity=256u64){value<-7u64};
  proc replacement=proc()->const u64 {return 2u64;};
  proc current=proc()->const u64 {return 1u64;};
  effect @reader=current;
  effect proc @action()->Item {behave @print(perform @reader()); return root(@arena);};
  current <-replacement;
  defer behave @action();
}
run();
